<h2><?=h($title)?></h2><div class="card p-4"><p>订单号：<?=h($order['order_no'])?></p><p><?=h($order['title'])?></p><p>原价：<?=money($order['amount'])?>　会员折扣：<?=money($order['discount'])?>　优惠码优惠：<?=money(isset($order['coupon_discount']) ? $order['coupon_discount'] : 0)?></p><?php if (!empty($order['coupon_code'])): ?><p>优惠码：<code><?=h($order['coupon_code'])?></code></p><?php endif; ?><p>应付：<b><?=money($order['pay_amount'])?></b></p><p>状态：<?=order_status_badge($order)?></p><?php if ($order['status'] === 'unpaid'): ?><a class="btn btn-primary" href="<?=h(url_to('index/pay/index', ['id' => $order['id']]))?>">去支付</a><?php if (!empty($order['coupon_code'])): ?><form method="post" class="d-inline" action="<?=h(url_to('index/order/removeCoupon'))?>"><?=csrf_field()?><input type="hidden" name="id" value="<?= (int)$order['id'] ?>"><button class="btn btn-outline-danger">移除优惠码</button></form><?php endif; ?><?php endif; ?></div>
